function specificityScore(prompt) {
  let score = 0;
  const checks = [
    [/classify|extract|draft|list|decide/i, 'concrete verb'],
    [/\{[^}]*\}|json/i, 'output shape'],
    [/\d+\s*(words|max|items|bullets)/i, 'size bound'],
    [/never|only|must|exactly/i, 'hard constraint'],
    [/audience|for a |tone/i, 'audience/tone'],
  ];
  for (const [re, label] of checks) if (re.test(prompt)) { score++; }
  return { score: score + '/5', prompt: prompt.slice(0, 40) + '...' };
}
const vague = 'Handle this complaint: ...';
const sharp = 'Classify into [late, damaged]. Output JSON {"category":...}. Max 40 words. Never promise refunds. Audience: first-time buyer.';
console.log(JSON.stringify(specificityScore(vague)));
console.log(JSON.stringify(specificityScore(sharp)));

